def backfill_stock_state(apps, schema_editor):
    """Record what each existing order is already doing to stock. Nothing in
    the stock counters is changed: an order that was paid took its units off
    the shelf, a cancelled or refunded one gave them back, and everything else
    still holds its reservation — exactly as the counters stand today."""
    Order = apps.get_model("orders", "Order")
    Payment = apps.get_model("payments", "Payment")
    Order.objects.filter(status__in=["cancelled", "refunded"]).update(stock_state="released")
    paid = Payment.objects.filter(status="completed").values_list("order_id", flat=True)
    Order.objects.exclude(status__in=["cancelled", "refunded"]).filter(id__in=paid).update(
        stock_state="taken"
    )


